<?php
namespace App\Http\Controllers;use App\Models\{Lead,CallLog,FollowUp,User,Order};use Illuminate\Http\Request;
class ReportController extends Controller{public function index(Request $r){$cid=$r->user()->company_id;$users=User::where('company_id',$cid)->withCount(['assignedLeads'])->get();$status=Lead::where('company_id',$cid)->selectRaw('lead_status_id,count(*) total')->groupBy('lead_status_id')->with('status')->get();return view('reports.index',['users'=>$users,'status'=>$status,'calls'=>CallLog::where('company_id',$cid)->whereBetween('created_at',[$r->date('from',today()->subDays(30))->startOfDay(),$r->date('to',today())->endOfDay()])->selectRaw('user_id,count(*) calls,sum(duration_seconds) duration')->groupBy('user_id')->with('user')->get(),'sales'=>Order::where('company_id',$cid)->sum('total_amount')]);}}
